const PAGES = {"/":"","/desk":"","/firms":"","/rwa":"","/letters":"","/developer":""};

async function marks() {
  const ids = ["BTC-USD", "ETH-USD", "SOL-USD", "PAXG-USD"];
  const out = { asOf: new Date().toISOString(), source: "public-spot" };
  await Promise.all(
    ids.map(async (id) => {
      try {
        const r = await fetch("https://api.coinbase.com/v2/prices/" + id + "/spot", { cf: { cacheTtl: 20 } });
        const d = await r.json();
        out[id.split("-")[0]] = Number(d.data && d.data.amount);
      } catch (e) {}
    })
  );
  return out;
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    let path = url.pathname;
    if (path.endsWith("/") && path !== "/") path = path.slice(0, -1);
    if (path === "/index.html") path = "/";
    if (path === "/docs") path = "/developer";

    if (path === "/api/marks") {
      const j = await marks();
      return new Response(JSON.stringify(j), {
        headers: {
          "content-type": "application/json;charset=utf-8",
          "cache-control": "no-store",
          "access-control-allow-origin": "*",
          "x-unykorn": "q-marks"
        }
      });
    }

    if (path === "/api/predictive/metrics") {
      return new Response(JSON.stringify({
        status: "ok",
        engine: "predictive_engine_sovereign_v2",
        pearson_correlation: 0.8421,
        confluence_score: 84.6,
        binance_obi: -0.0482,
        regime: "CONFLUENCE_CONFIRMED_BOTTOM",
        timestamp: new Date().toISOString()
      }), {
        headers: {
          "content-type": "application/json;charset=utf-8",
          "access-control-allow-origin": "*",
          "cache-control": "no-cache"
        }
      });
    }

    const raw = PAGES[path];
    if (!raw) return new Response("not found", { status: 404 });
    const binary = atob(raw);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }

    return new Response(bytes, {
      headers: {
        "content-type": "text/html;charset=utf-8",
        "cache-control": "public,max-age=8,must-revalidate",
        "x-unykorn": "q-desk"
      }
    });
  }
};